<style scoped lang="scss" src="./fundraiser-social-block.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import {
  SocialType,
  SocialTypeValues,
} from "./fundraiser-social-block.constants";
import { has } from "../../util/has";
import Meter from "../meter/meter.vue";
import { MeterMode } from "../meter/meter.constants.js";
import { CurrencyNotation, CurrencyNotationValues } from "../constants";

/**
 * This is a component to show basic information of a social card
 * It can be a person or an organization
 */
@Component({
  components: {
    Meter,
  },
})
export default class FundraiserSocialBlock extends Vue {
  @Prop({
    type: String,
    default: SocialType.PERSON,
    validator: has(SocialTypeValues),
  })
  socialType;

  @Prop({
    type: String,
    default: "No Name",
  })
  name;

  @Prop({
    type: String,
    default: "Team",
  })
  groupType;

  @Prop({
    type: [Date, Number, String],
    default: new Date().toISOString().slice(0, 10),
  })
  joinedDate;

  @Prop({
    type: Number,
    default: 0,
  })
  memberNumber;

  @Prop({
    type: Number,
    default: 0,
  })
  collected;

  @Prop({
    type: Number,
    default: 100,
  })
  goal;

  @Prop({
    type: String,
    default: "",
  })
  image;

  @Prop({
    type: String,
    default: CurrencyNotation.USD,
    validator: has(CurrencyNotationValues),
  })
  currency;

  isTeam() {
    return Boolean(this.socialType === SocialType.TEAM);
  }

  meterMode = MeterMode.MEDIUM;

  get joinedDateSummary() {
    const options = { year: "numeric", month: "long" };

    if (
      typeof this.joinedDate === "number" ||
      typeof this.joinedDate === "string"
    ) {
      const joinedDate = new Date(this.joinedDate);

      if (joinedDate.toDateString() === "Invalid Date") {
        console.warn("Wrong date format");
      }

      return `Joined ${joinedDate.toLocaleString("en-US", options)}`;
    }

    return `Joined ${this.joinedDate.toLocaleString("en-US", options)}`;
  }

  get teamSummary() {
    if (this.memberNumber < 1000) return `${this.memberNumber} Members`;

    const units = [0, 1000, 1000000, 1000000000];
    const chars = ["", "K", "M", "B"];

    let i = 0;

    while (i < units.length) {
      if (this.memberNumber > units[i]) {
        i++;
      } else {
        break;
      }
    }

    const unit = units[i - 1];

    return `${(this.memberNumber / unit).toFixed(1)} ${chars[i - 1]} Members`;
  }

  handleClick() {
    /**
     * Emits when the block is clicked
     *
     * @event click
     */
    this.$emit("click");
  }
}
</script>

<template>
  <div class="FundraiserSocialBlock" @click="handleClick">
    <div class="FundraiserSocialBlock__Content">
      <div
        class="FundraiserSocialBlock__Image"
        v-bind:style="{ backgroundImage: `url(${image})` }"
      />
      <div class="FundraiserSocialBlock__Middle">
        <div class="FundraiserSocialBlock__Name">{{ this.name }}</div>
        <div v-if="isTeam()" class="FundraiserSocialBlock__Detail">
          {{ this.groupType }}<span class="FundraiserSocialBlock__Dot">•</span
          >{{ this.teamSummary }}
        </div>
        <div v-else class="FundraiserSocialBlock__Detail">
          {{ this.joinedDateSummary }}
        </div>
      </div>
      <Meter
        :collected="collected"
        :goal="goal"
        :mode="meterMode"
        :currency="currency"
      />
    </div>
  </div>
</template>
